"""File helpers."""

import logging

from app.errors import AppError

log = logging.getLogger("app.io")


def read_config(path: str) -> str:
    with open(path, encoding="utf-8") as fh:
        return fh.read()


def read_all(paths: list[str]) -> list[str]:
    contents = []
    for path in paths:
        try:
            contents.append(read_config(path))
        except OSError as e:
            log.warning("Failed to read file", extra={"path": path})
            raise AppError(f"Failed to read file: {path}", cause=e) from e
    return contents
